import { useState } from 'react';
import './dashboard.css';

function Dashboard({ userName, onLogout }) {
	const [tasks, setTasks] = useState([
		{ id: 1, title: 'Plan today\'s tasks', done: true },
		{ id: 2, title: 'Complete project work', done: false },
		{ id: 3, title: 'Review your progress', done: false },
	]);

	function toggleTask(id) {
		setTasks(tasks.map((task) => (
			task.id === id ? { ...task, done: !task.done } : task
		)));
	}

	const completedTasks = tasks.filter((task) => task.done).length;

	return (
		<main className="dashboard-page">
			<header className="dashboard-header">
				<h1>Task Manager</h1>
				<button className="logout-button" type="button" onClick={onLogout}>Logout</button>
			</header>

			<section className="dashboard-content">
				<p className="dashboard-label">Your dashboard</p>
				<h2>Welcome, {userName}!</h2>
				<p className="dashboard-intro">Here is what you have planned for today.</p>

				<div className="summary-box">
					<strong>{completedTasks} of {tasks.length}</strong>
					<span>tasks completed</span>
				</div>

				<section className="tasks-box" aria-labelledby="tasks-title">
					<h3 id="tasks-title">My Tasks</h3>
					{tasks.map((task) => (
						<label className={`task-item ${task.done ? 'completed' : ''}`} key={task.id}>
							<input type="checkbox" checked={task.done} onChange={() => toggleTask(task.id)} />
							<span>{task.title}</span>
						</label>
					))}
				</section>
			</section>
		</main>
	);
}

export default Dashboard;
